import{_ as a,o as e,c as n,a4 as t}from"./chunks/framework.CQGI5ZO3.js";const h=JSON.parse('{"title":"xs-snapshot(1)","description":"Resume verified partial data, reuse unchanged snapshot files, and control writes.","frontmatter":{"title":"xs-snapshot(1)","description":"Resume verified partial data, reuse unchanged snapshot files, and control writes.","manual":"xs-snapshot(1)","manualName":"Resume & snapshots","sectionNumber":"1"},"headers":[],"relativePath":"snapshots.md","filePath":"snapshots.md"}'),o={name:"snapshots.md"};function l(i,s,p,c,r,d){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="xs-snapshot-1" tabindex="-1">xs-snapshot(1) <a class="header-anchor" href="#xs-snapshot-1" aria-label="Permalink to &quot;xs-snapshot(1)&quot;">​</a></h1><div class="manual-deck"><strong>Resume &amp; snapshots</strong><p>Resume verified partial data, reuse unchanged snapshot files, and control writes.</p></div><h2 id="resume" tabindex="-1">PARTIAL TRANSFERS <a class="header-anchor" href="#resume" aria-label="Permalink to &quot;PARTIAL TRANSFERS {#resume}&quot;">​</a></h2><div class="example-caption">Retain partial data and show progress</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>With <code>--partial</code> or <code>-P</code>, xsync verifies an existing destination prefix on both sides before reusing it. A matching prefix avoids sending the same bytes again; a mismatch sends the file in full. Retained interrupted output contains its completed contiguous prefix.</p><aside class="manual-note"><span>NOTE</span><p>Small files up to 512 KiB use the whole-file path. A protocol-3 peer has no verified-prefix resume feature and transfers the file in full.</p></aside><h2 id="delta" tabindex="-1">DELTA AND WHOLE-FILE TRANSFERS <a class="header-anchor" href="#delta" aria-label="Permalink to &quot;DELTA AND WHOLE-FILE TRANSFERS {#delta}&quot;">​</a></h2><div class="example-caption">Allow verified reuse</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> --no-whole-file</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><div class="example-caption">Disable resume and block matching</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> --whole-file</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>Large changed local and remote files can reuse verified blocks from a readable existing destination. Eligible APFS clones remain preferred for local copies. <code>-W</code> disables resume and delta block matching.</p><h2 id="link-dest" tabindex="-1">SNAPSHOT REUSE <a class="header-anchor" href="#link-dest" aria-label="Permalink to &quot;SNAPSHOT REUSE {#link-dest}&quot;">​</a></h2><div class="example-caption">Reuse a previous snapshot</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> --link-dest=../previous/</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> snapshots/current/</span></span></code></pre></div><p>Relative <code>--link-dest</code> paths start at the destination directory. In this example, the basis is <code>snapshots/previous/</code>. Up to 20 previous snapshot directories may be supplied.</p><p>Unchanged files with matching requested metadata become hard links. Changed files, different requested metadata, or cross-device links create independent copies. A previous snapshot may also supply a read-only delta basis.</p><div class="example-caption">A dated snapshot that hard-links unchanged files</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-ai</span><span style="color:#DEDEDE;"> --link-dest=../2026-10-09</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> snapshots/2026-10-10/</span></span>
<span class="line"><span style="color:#DEDEDE;">stat </span><span style="color:#DEDEDE;">-c</span><span style="color:#DEDEDE;"> &quot;%h links  %n&quot;</span><span style="color:#DEDEDE;"> snapshots/2026-10-10/notes.txt</span><span style="color:#DEDEDE;"> snapshots/2026-10-10/docs/guide.md</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>created directory snapshots/2026-10-10
&gt;f.st...... notes.txt
1 links  snapshots/2026-10-10/notes.txt
2 links  snapshots/2026-10-10/docs/guide.md</code></pre></div><h2 id="shared-files" tabindex="-1">SHARED FILES <a class="header-anchor" href="#shared-files" aria-label="Permalink to &quot;SHARED FILES {#shared-files}&quot;">​</a></h2><aside class="manual-note"><span>SNAPSHOTS</span><p>Hard-linked snapshots share the same inode. Later in-place writes or metadata changes to an already shared destination can affect other links. Create a new snapshot directory and keep old snapshots read-only by workflow.</p></aside><h2 id="atomic" tabindex="-1">ATOMIC AND IN-PLACE OUTPUT <a class="header-anchor" href="#atomic" aria-label="Permalink to &quot;ATOMIC AND IN-PLACE OUTPUT {#atomic}&quot;">​</a></h2><p>New byte-copied files are atomic by default: xsync writes a temporary name and publishes it by rename after verification. <code>--no-atomic</code> writes new files directly; <code>--inplace</code> explicitly writes destination files in place.</p><div class="example-caption">State the default atomic policy explicitly</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> --atomic</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>Direct writing changes interruption behavior and can leave incomplete files under final names. Atomic staging and retained partials also need destination disk space.</p>`,28)])])}const D=a(o,[["render",l]]);export{h as __pageData,D as default};
